from collections import Counter

def key(word):
    # Two words are anagrams exactly when their sorted letters are equal.
    return "".join(sorted(word))

def solution(words, queries):
    # Precompute once: how many dictionary words share each anagram key.
    # Duplicates in words are counted separately, which Counter does for free.
    groups = Counter(key(w) for w in words)
    # Each query is now one sort plus one dict lookup. Counter gives 0 for a missing key.
    return [groups[key(q)] for q in queries]

