def solution(words, queries):
    # Compare every query with every word. O(Q * W * L log L).
    answer = []
    for q in queries:
        target = sorted(q)
        count = 0
        for w in words:
            if len(w) == len(q) and sorted(w) == target:
                count += 1
        answer.append(count)
    return answer
